CREATE TABLE IF NOT EXISTS PASSENGER (ID BIGINT AUTO_INCREMENT PRIMARY KEY, "name" TEXT NOT NULL, EMAIL TEXT NOT NULL);
ALTER TABLE PASSENGER ADD CONSTRAINT PASSENGER_EMAIL_UNIQUE UNIQUE (EMAIL);
CREATE TABLE IF NOT EXISTS DRIVER (ID BIGINT AUTO_INCREMENT PRIMARY KEY, FIRST_NAME VARCHAR(50) NOT NULL, LAST_NAME VARCHAR(50) NOT NULL);
CREATE TABLE IF NOT EXISTS TAXI (ID BIGINT AUTO_INCREMENT PRIMARY KEY, MAKE_AND_MODEL JSON NOT NULL, CAR_COLOR VARCHAR(50) NOT NULL, DRIVER_ID BIGINT NOT NULL, CONSTRAINT FK_TAXI_DRIVER_ID__ID FOREIGN KEY (DRIVER_ID) REFERENCES DRIVER(ID) ON DELETE RESTRICT ON UPDATE RESTRICT);
CREATE TABLE IF NOT EXISTS TAXI_RIDE (ID BIGINT AUTO_INCREMENT PRIMARY KEY, PASSENGER_ID BIGINT NOT NULL, TAXI_ID BIGINT NOT NULL, PICKUP_LOCATION TEXT NOT NULL, AMOUNT DECIMAL(13, 2) NOT NULL, CURRENCY VARCHAR(3) NOT NULL, STATUS INT DEFAULT 0 NOT NULL, CONSTRAINT FK_TAXI_RIDE_PASSENGER_ID__ID FOREIGN KEY (PASSENGER_ID) REFERENCES PASSENGER(ID) ON DELETE RESTRICT ON UPDATE RESTRICT, CONSTRAINT FK_TAXI_RIDE_TAXI_ID__ID FOREIGN KEY (TAXI_ID) REFERENCES TAXI(ID) ON DELETE RESTRICT ON UPDATE RESTRICT);